import{_ as a,a as t,c as i,ac as n}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"第二册：实践与进步 · Lesson 88 Trapped in a mine","description":"学习 被动语态与信息重点，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第二册：实践与进步 · Lesson 88 Trapped in a mine","description":"学习 被动语态与信息重点，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第2册课时","summary":"学习 被动语态与信息重点，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第二册：实践与进步 · Lesson 87 A perfect alibi","link":"/life/english/new-concept/book-2/unit-04/lesson-087"},"next":{"text":"第二册：实践与进步 · Lesson 89 A slip of the tongue","link":"/life/english/new-concept/book-2/unit-04/lesson-089"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第二册：实践与进步 · Lesson 87 A perfect alibi","link":"/life/english/new-concept/book-2/unit-04/lesson-087"},"next":{"text":"第二册：实践与进步 · Lesson 89 A slip of the tongue","link":"/life/english/new-concept/book-2/unit-04/lesson-089"}},"headers":[],"relativePath":"life/english/new-concept/book-2/unit-04/lesson-088.md","filePath":"life/english/new-concept/book-2/unit-04/lesson-088.md"}'),l={name:"life/english/new-concept/book-2/unit-04/lesson-088.md"};function o(r,e,s,h,d,p){return t(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="第二册-实践与进步-·-lesson-88-trapped-in-a-mine" tabindex="-1">第二册：实践与进步 · Lesson 88 Trapped in a mine <a class="header-anchor" href="#第二册-实践与进步-·-lesson-88-trapped-in-a-mine" aria-label="Permalink to &quot;第二册：实践与进步 · Lesson 88 Trapped in a mine&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-2/contents">本册目录</a> · <a href="/life/english/new-concept/book-2/unit-04/overview">单元 4</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>救援需要持续沟通、供氧和钻孔，进度报告应避免把计划写成成功；练习将来条件与被动。本课的语言观察是：will be lowered 表计划将物资放下，不说明已经送达；have been supplied 表已经获得供应。受困者作主语时被动突出受助情况。完成学习后，请写一份虚构救援进度：已完成一项、正在做一项、还需达到的条件。</p><p>本课以主题阅读带动语言分析，学习重点如下。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>trap</td><td>/træp/</td><td>v.</td><td>困住</td><td>be trapped underground</td></tr><tr><td>oxygen</td><td>/ˈɒksɪdʒən/</td><td>n.</td><td>氧气</td><td>an oxygen supply</td></tr><tr><td>drill</td><td>/drɪl/</td><td>v.</td><td>钻孔</td><td>drill a hole</td></tr><tr><td>rescue</td><td>/ˈreskjuː/</td><td>v.</td><td>营救</td><td>rescue a climber</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>be trapped in — 被困在某处</li><li>keep in touch with — 与……保持联系</li></ul><h2 id="语法讲解-被动语态与信息重点" tabindex="-1">语法讲解：被动语态与信息重点 <a class="header-anchor" href="#语法讲解-被动语态与信息重点" aria-label="Permalink to &quot;语法讲解：被动语态与信息重点&quot;">​</a></h2><p>被动语态由相应时态的 be 加过去分词构成，把动作的承受者放在主语位置。时态变化主要体现在 be 上，过去分词本身不随主语改变。只有可以带宾语的相关用法才能形成通常的被动句，happen、arrive 等不及物动词不能照搬。执行者未知、不重要或已经显然时可以省略 by 短语；需要追责或形成对比时则应保留。本课应用：will be lowered 表计划将物资放下，不说明已经送达；have been supplied 表已经获得供应。受困者作主语时被动突出受助情况。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>Fresh air will be supplied through a narrow pipe.</p></blockquote><p>新鲜空气将通过一根细管输送进去。</p><p>will be supplied 是将来被动，through 引出通道，Fresh air 不可数。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>through a pipe 指穿过管道内部；across a pipe 则是横跨，不适合输送通道。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>重读 will 与 have reached 的差别，不能把未来供应读成已完成行动。可朗读本页原创示范并自行录音回听；本页不提供教材录音。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>Fresh air will be supplied through a narrow pipe. Rescuers have reached the chamber with a radio cable. Drilling will continue until the opening is wide enough.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>写一份虚构救援进度：已完成一项、正在做一项、还需达到的条件。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>第一句的组织方式：will be supplied 是将来被动，through 引出通道，Fresh air 不可数。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：through a pipe 指穿过管道内部；across a pipe 则是横跨，不适合输送通道。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>补全：Air will ___ supplied through the pipe.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> be</p><p><strong>解析：</strong> 将来被动使用 will be 加过去分词。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>救援人员通过什么建立联系？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> A radio cable.</p><p><strong>解析：</strong> 示范说明通信电缆已经到达，救援通道仍在钻。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>填 through/across：The cable runs ___ the tunnel.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> through</p><p><strong>解析：</strong> 电缆沿隧道内部通过，使用 through。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：被动语态与信息重点。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-2/unit-04/grammar">单元语法</a> · <a href="/life/english/new-concept/book-2/unit-04/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-2/unit-04/review">单元自测</a></p><p><a href="/life/english/new-concept/book-2/unit-04/lesson-087">上一课</a> · <a href="/life/english/new-concept/book-2/unit-04/overview">单元目录</a> · <a href="/life/english/new-concept/book-2/unit-04/lesson-089">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const b=a(l,[["render",o]]);export{u as __pageData,b as default};
